#include "sdk_world.h"
#include <cstdio>
#include <memory>
#include <stdexcept>
using namespace tactics;
static void require(bool x,const char*s){if(!x){std::printf("SHIELD_CLOCK_FAIL %s\n",s);throw std::runtime_error(s);}}
static void ledger(World&w,const char*phase){const auto b=w.me.buffs();double value=0;int ticks=-1;if(b.has_shield()){const auto s=b.get<bc::buff_shield>();value=s.value;ticks=s.duration;}std::printf("SHIELD_CLOCK %s round=%d actor=%d hp=%.2f shield=%.2f ticks=%d read=%.2f,%d\n",phase,w.round,w.self.id,w.me.health(),value,ticks,w.self.shield,w.self.shield_ticks);}
int main(){Geometry geo;Memory memory;std::unique_ptr<World>ptr;int group=-1,phase=0;Pos target{};while(true){try{if(bc::is_draft()){auto old=bc::draft::current_draft(bc::team::ally);for(auto p:{bc::champion_draft::varg,bc::champion_draft::ryth,bc::champion_draft::willow})if(std::find(old.begin(),old.end(),p)==old.end()){bc::draft::pick(p);break;}}else if(bc::detail::sdk_my_team()==1){bc::end_turn();continue;}else if(phase<8&&int(bc::self().champion_name())==10){if(!geo.initialized){geo.initialize();bc::end_turn();continue;}if(group<0){int d=unreachable;for(unsigned i=0;i<geo.groups.size();++i)if(geo.groups[i].spawns.size()==1&&geo.groups[i].initial_strength>0){int next=geo.at(geo.home,geo.groups[i].spawns.front().pos);if(next<d){d=next;group=i;}}require(group>=0,"single native damaging camp");target=geo.groups[group].spawns.front().pos;}if(!geo.goal_field(target,1)||bc::fuel_remaining()<65000){bc::end_turn();continue;}if(!ptr)ptr=std::make_unique<World>(geo,memory);auto&w=*ptr;w.refresh();if(phase==0){if(distance(w.self.pos,target)<=1)phase=1;else if(auto next=w.toward(target,1))require(w.me.move_absolute(sdk(*next)),"actual approach");}else if(phase==1){require(w.groups[group].camps.size()==1&&w.groups[group].camps.front().strength==20,"actual native Wolf20");require(w.me.abilities()[1].use(),"actual Varg shield accepted");auto c=w.camp(w.groups[group].camps.front().id);require(c.has_value(),"visible native Wolf");w.me.attack(*c);w.refresh(true);ledger(w,"IMMEDIATE");phase=2;}else{ledger(w,"NEXT");if(++phase==8)std::printf("SHIELD_CLOCK_PASS\n");}}}catch(const std::exception&e){std::printf("SHIELD_CLOCK_EXCEPTION %s\n",e.what());phase=8;}bc::end_turn();}}
